body.script:
const phone = document.querySelector('.phone');
const leftChoice = document.querySelector('.choice-trigger.left');
const middleChoice = document.querySelector('.choice-trigger.middle');
const rightChoice = document.querySelector('.choice-trigger.right');
const chooseButton = document.querySelector('.choose-trigger');
const backButton = document.querySelector('.back-trigger');
const shareButton = document.querySelector('.share-trigger');
const shareClose = document.querySelector('.share-close');
const reselectButton = document.querySelector('.reselect-trigger');
const retryLeftButton = document.querySelector('.retry-left-trigger');
const retryMiddleButton = document.querySelector('.retry-middle-trigger');
const retryRightButton = document.querySelector('.retry-right-trigger');
const retrySubmitButton = document.querySelector('.retry-submit-trigger');
const resultCount = document.querySelector('.result-count');
const retryCount = document.querySelector('.retry-count');
const retryNote = document.querySelector('.retry-note');
const dateYear = document.querySelector('.date-year');
const dateValue = document.querySelector('.date-value');
const shareBackDate = document.querySelector('.share-back-date');
const currentDate = new Date();
dateYear.textContent = String(currentDate.getFullYear());
dateValue.textContent = `${String(currentDate.getMonth() + 1).padStart(2, '0')}/${String(currentDate.getDate()).padStart(2, '0')}`;
shareBackDate.textContent = dateValue.textContent;
const variantImages = document.querySelectorAll('.food-variant img');
const variantLabels = document.querySelectorAll('.food-label');
const foods = [
  { src: '', name: '烧烤' },
  { src: 'foods/food-01-spicy-stir-fry.webp', name: '麻辣香锅' },
  { src: 'foods/food-03-chicken-pot.webp', name: '香菇鸡煲' },
  { src: 'foods/food-02-pickled-fish.webp', name: '酸菜鱼' },
  { src: 'foods/food-04-claypot-rice.webp', name: '煲仔饭' },
  { src: 'foods/food-05-dumplings.webp', name: '水饺' },
  { src: 'foods/food-06-noodles.webp', name: '招牌拌面' },
  { src: 'foods/food-07-sushi.webp', name: '寿司拼盘' },
  { src: 'foods/food-10-chicken-rice.webp', name: '鸡肉盖饭' }
];
let foodIndex = 0;
let remainingCount = 8;
function updateRemainingCount() {
  resultCount.textContent = String(remainingCount);
  retryCount.textContent = String(remainingCount);
  retryNote.textContent = `快点选好吃饭吧，还有${remainingCount}次机会哦`;
  reselectButton.disabled = remainingCount <= 0;
  reselectButton.setAttribute('aria-disabled', String(remainingCount <= 0));
}
function randomizeFood() {
  let nextIndex;
  do {
    nextIndex = Math.floor(Math.random() * foods.length);
  } while (foods.length > 1 && nextIndex === foodIndex);
  foodIndex = nextIndex;
  const food = foods[foodIndex];
  phone.classList.toggle('has-food-variant', foodIndex !== 0);
  if (foodIndex !== 0) {
    variantImages.forEach((image) => { image.src = food.src; });
    variantLabels.forEach((label) => { label.textContent = food.name; });
  }
}
function selectChoice(choice) {
  phone.classList.toggle('is-left-selected', choice === 'left');
  phone.classList.toggle('is-right-selected', choice === 'right');
  leftChoice.setAttribute('aria-pressed', String(choice === 'left'));
  middleChoice.setAttribute('aria-pressed', String(choice === 'middle'));
  rightChoice.setAttribute('aria-pressed', String(choice === 'right'));
}
leftChoice.addEventListener('click', () => {
  selectChoice('left');
});
middleChoice.addEventListener('click', () => {
  selectChoice('middle');
});
rightChoice.addEventListener('click', () => {
  selectChoice('right');
});
chooseButton.addEventListener('click', () => {
  randomizeFood();
  phone.classList.add('show-result');
});
backButton.addEventListener('click', () => {
  remainingCount = 9;
  updateRemainingCount();
  phone.classList.remove('show-result');
});
shareButton.addEventListener('click', () => {
  phone.classList.add('show-share');
});
shareClose.addEventListener('click', () => {
  phone.classList.remove('show-share');
});
reselectButton.addEventListener('click', () => {
  if (remainingCount <= 0) return;
  phone.classList.add('show-retry');
});
retryLeftButton.addEventListener('click', () => {
  phone.classList.add('retry-left-selected');
  phone.classList.remove('retry-right-selected');
});
retryMiddleButton.addEventListener('click', () => {
  phone.classList.remove('retry-left-selected');
  phone.classList.remove('retry-right-selected');
});
retryRightButton.addEventListener('click', () => {
  phone.classList.remove('retry-left-selected');
  phone.classList.add('retry-right-selected');
});
retrySubmitButton.addEventListener('click', () => {
  if (remainingCount <= 0) return;
  remainingCount = Math.max(0, remainingCount - 1);
  updateRemainingCount();
  randomizeFood();
  phone.classList.remove('show-retry');
  phone.classList.remove('retry-left-selected', 'retry-right-selected');
  phone.classList.add('show-result');
});
